def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            min_y = min(y for y, x in cells)
            min_x = min(x for y, x in cells)
            shape = frozenset((y - min_y, x - min_x) for y, x in cells)
            components.append((color, cells, shape))

    color_by_shape = {}
    for color, cells, shape in components:
        if color != 1:
            color_by_shape[shape] = color

    result = [row[:] for row in grid]
    for color, cells, shape in components:
        if color == 1 and shape in color_by_shape:
            replacement = color_by_shape[shape]
            for y, x in cells:
                result[y][x] = replacement
    return result
